def comment_tree(post_id):
    rows = db.execute('SELECT * FROM comments WHERE post_id = %s ORDER BY created_at', (post_id,)).fetchall()
    by_parent = {}
    for r in rows:
        by_parent.setdefault(r.parent, []).append(r)
    def attach(node):
        node.replies = [attach(c) for c in by_parent.get(node.id, [])]
        return node
    return [attach(r) for r in by_parent.get(None, [])]

